    "\n"
    "/* ==== 00-i18n.js ==== */\n"
    "/* ---- Language --------------------------------------------------------- */\n"
    "\n"
    "/* t() looks a string up in LANG[lang] and falls back to the English\n"
    "   key. LANG is generated from ui/lang/*.json at build time. {name}\n"
    "   placeholders are filled after the lookup. */\n"
    "const LANGS = [['', 'English'], ['pt-BR', 'Português (Brasil)'], ['es', 'Español']];\n"
    "\n"
    "let lang = '';\n"
    "try { lang = localStorage.getItem('lang') || ''; } catch (e) { lang = ''; }\n"
    "/* lang= in the query string or the hash overrides the stored choice\n"
    "   for this window. */\n"
    "{\n"
    "  const q = new URLSearchParams(location.search).get('lang') ||\n"
    "            new URLSearchParams(location.hash.slice(1)).get('lang');\n"
    "\n"
    "  if (q !== null && LANGS.some(([code]) => code === q)) lang = q;\n"
    "}\n"
    "\n"
    "/* Keys and translations may carry &middot;, &mdash; and &amp;. The\n"
    "   page renders text nodes, so they become the characters. */\n"
    "function entities(s) {\n"
    "  return s.replace(/&middot;/g, '·').replace(/&mdash;/g, '—').replace(/&amp;/g, '&');\n"
    "}\n"
    "\n"
    "function t(s, v) {\n"
    "  const d = LANG[lang];\n"
    "  let out = entities((d && d[s]) || s);\n"
    "\n"
    "  if (v) for (const k in v) out = out.split('{' + k + '}').join(String(v[k]));\n"
    "  return out;\n"
    "}\n"
    "\n"
    "/* t() with elements among the values: the string is split on each\n"
    "   placeholder and returned as an array of strings and nodes. */\n"
    "function tv(s, v) {\n"
    "  let parts = [t(s)];\n"
    "\n"
    "  for (const k in v) {\n"
    "    const next = [];\n"
    "\n"
    "    for (const p of parts) {\n"
    "      if (typeof p !== 'string') { next.push(p); continue; }\n"
    "      p.split('{' + k + '}').forEach((bit, i) => {\n"
    "        if (i) next.push(v[k]);\n"
    "        if (bit) next.push(bit);\n"
    "      });\n"
    "    }\n"
    "    parts = next;\n"
    "  }\n"
    "  return parts;\n"
    "}\n"
    "\n"
    "/* Stores the choice in this browser and reloads. */\n"
    "function setLang(code) {\n"
    "  try { localStorage.setItem('lang', code); } catch (e) { /* private window */ }\n"
    "  location.reload();\n"
    "}\n"
    "\n"
    "/* ==== 01-util.js ==== */\n"
    "/* ---- Small helpers, shared by every tab -------------------------------- */\n"
    "\n"
    "const BADGE = 'https://media.retroachievements.org/Badge/';\n"
    "const MEDIA = 'https://media.retroachievements.org';\n"
    "\n"
    "/* True when the page was opened from another device. Settings, the\n"
    "   follow switch and QUIT are then hidden. */\n"
    "const REMOTE = !['127.0.0.1', 'localhost', '::1', '[::1]'].includes(location.hostname);\n"
    "\n"
    "const TABS = ['live', 'library', 'game', 'boards', 'settings'];\n"
    "\n"
    "function hms(s) {\n"
    "  const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60);\n"
    "  return h + ':' + String(m).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');\n"
    "}\n"
    "\n"
    "function pct(a, b) { return b ? Math.round(a * 100 / b) : 0; }\n"
    "\n"
    "/* rc_client's measured_percent is already 0..100. */\n"
    "function pctClamp(v) { return Math.max(0, Math.min(100, +v || 0)); }\n"
    "\n"
    "function ago(sec) {\n"
    "  if (sec < 60) return t('{n} s', { n: sec });\n"
    "  if (sec < 3600) return t('{n} min', { n: Math.floor(sec / 60) });\n"
    "  return t('{h} h {m} min', { h: Math.floor(sec / 3600), m: Math.floor((sec % 3600) / 60) });\n"
    "}\n"
    "\n"
    "/* The whole line is one dictionary string. */\n"
    "function agoText(sec) { return t('{time} ago', { time: ago(sec) }); }\n"
    "\n"
    "function medianText(s) {\n"
    "  return Math.floor(s / 3600) + 'h' + String(Math.floor(s % 3600 / 60)).padStart(2, '0');\n"
    "}\n"
    "\n"
    "function badgeUrl(a, locked) { return BADGE + a.badge + (locked ? '_lock' : '') + '.png'; }\n"
    "\n"
    "/* Rank in the progression-path order; untyped rows take 2. */\n"
    "const TYPE_RANK = { progression: 0, win_condition: 1, missable: 3 };\n"
    "\n"
    "/* achType() maps rc_client's numeric type or the Web API's string to\n"
    "   'missable', 'progression', 'win_condition' or ''. */\n"
    "const TYPE_NAMES = ['', 'missable', 'progression', 'win_condition'];\n"
    "\n"
    "function achType(a) {\n"
    "  return typeof a.type === 'number' ? (TYPE_NAMES[a.type] || '')\n"
    "                                    : (a.type || '').toLowerCase();\n"
    "}\n"
    "\n"
    "function onPath(a) {\n"
    "  const ty = achType(a);\n"
    "  return ty === 'progression' || ty === 'win_condition';\n"
    "}\n"
    "\n"
    "/* Time cost of a set from its medians: beaten is the latest median on\n"
    "   the intended path, full the latest of all. */\n"
    "function setEstimates(list, medOf) {\n"
    "  const meds = list.map(medOf).filter(m => m > 0);\n"
    "  const path = list.filter(onPath).map(medOf).filter(m => m > 0);\n"
    "\n"
    "  return { full: meds.length ? Math.max(...meds) : 0,\n"
    "           beaten: path.length ? Math.max(...path) : 0 };\n"
    "}\n"
    "\n"
    "/* UP NEXT: the four locked achievements with the lowest medians. The\n"
    "   first locked progression or win-condition achievement takes the last\n"
    "   slot when it is not among them. */\n"
    "function upNextPick(list, med) {\n"
    "  const byMed = (x, y) => med(x) - med(y);\n"
    "  const locked = list.filter(a => a.state === 1 && med(a) > 0);\n"
    "  const spine = locked.filter(onPath).sort(byMed);\n"
    "  const next = locked.sort(byMed).slice(0, 4);\n"
    "\n"
    "  if (spine.length && !next.includes(spine[0])) {\n"
    "    next[next.length - 1] = spine[0];\n"
    "    next.sort(byMed);\n"
    "  }\n"
    "  return { next, prog: spine.length ? spine[0] : null };\n"
    "}\n"
    "\n"
    "/* Locked missables whose median is at or before the latest median\n"
    "   among the unlocked progression and win-condition achievements. */\n"
    "function possiblyMissed(list, med) {\n"
    "  const passed = Math.max(0, ...list.filter(a => a.state === 2 && onPath(a)).map(med));\n"
    "  const out = new Set();\n"
    "\n"
    "  for (const a of list)\n"
    "    if (a.state === 1 && achType(a) === 'missable' && med(a) > 0 && med(a) <= passed)\n"
    "      out.add(a.id);\n"
    "  return out;\n"
    "}\n"
    "\n"
    "function sortAchievements(list, order) {\n"
    "  const byAuthor = (a, b) => a.order - b.order;\n"
    "\n"
    "  if (order === 'median')\n"
    "    /* Never-unlocked-by-anyone (median 0) goes to the end. */\n"
    "    return list.sort((a, b) =>\n"
    "      (a.median > 0 ? a.median : Infinity) - (b.median > 0 ? b.median : Infinity) || byAuthor(a, b));\n"
    "  if (order === 'type')\n"
    "    return list.sort((a, b) =>\n"
    "      (TYPE_RANK[achType(a)] ?? 2) - (TYPE_RANK[achType(b)] ?? 2) || byAuthor(a, b));\n"
    "  return list.sort(byAuthor);\n"
    "}\n"
    "\n"
    "/* ==== 02-store.js ==== */\n"
    "/* ---- The store: signals the components read ---------------------------- */\n"
    "\n"
    "const { h, render, Fragment } = require('preact');\n"
    "const { useState, useEffect, useRef, useMemo } = require('preact/hooks');\n"
    "const { signal, computed, effect, batch } = require('@preact/signals');\n"
    "const html = require('htm').bind(h);\n"
    "\n"
    "/* Slow state: a full /state once a second and on anything structural,\n"
    "   what the user clicked, what the tabs fetched. */\n"
    "const S = {\n"
    "  state: signal(null),          /* the last full state from the client */\n"
    "  profile: signal(null),        /* /profile: name and points */\n"
    "  version: signal(''),\n"
    "  tab: signal('live'),\n"
    "  gameId: signal(0),            /* the game open on GAME and BOARDS */\n"
    "  library: signal(null),\n"
    "  libraryAt: 0,\n"
    "  libFilter: signal('all'),\n"
    "  libConsoles: signal(new Set()),   /* empty = every console */\n"
    "  libConsolesOpen: signal(false),\n"
    "  gameSort: signal('author'),\n"
    "  gameFilter: signal('all'),\n"
    "  gameCache: {},                /* id -> /game answer */\n"
    "  gameTick: signal(0),          /* bumped when the cache changes */\n"
    "  boardsCache: {},\n"
    "  boardsTick: signal(0),\n"
    "  openBoards: signal(new Set()),\n"
    "  liveMeta: signal({ id: 0, byId: null, icon: '' }),  /* medians for the running game */\n"
    "  toast: signal(null),\n"
    "  powerOn: signal(0),           /* bumped when the console starts streaming */\n"
    "  closed: signal(false),\n"
    "  error: signal(''),\n"
    "  hidden: signal(loadHidden())  /* game id -> achievement ids kept out of UP NEXT */\n"
    "};\n"
    "\n"
    "/* Hidden achievements live in this browser's localStorage under 'hidden'. */\n"
    "function loadHidden() {\n"
    "  try { return JSON.parse(localStorage.getItem('hidden') || '{}') || {}; } catch (e) { return {}; }\n"
    "}\n"
    "\n"
    "function setHidden(gameId, ids) {\n"
    "  const h = Object.assign({}, S.hidden.value);\n"
    "  if (ids.length) h[gameId] = ids; else delete h[gameId];\n"
    "  S.hidden.value = h;\n"
    "  try { localStorage.setItem('hidden', JSON.stringify(h)); } catch (e) { /* private window */ }\n"
    "}\n"
    "\n"
    "function hideAch(gameId, id) {\n"
    "  const cur = S.hidden.value[gameId] || [];\n"
    "  if (!cur.includes(id)) setHidden(gameId, cur.concat(id));\n"
    "}\n"
    "\n"
    "function showHidden(gameId) { setHidden(gameId, []); }\n"
    "\n"
    "/* Fast state: the numbers a delta carries every snapshot, one signal\n"
    "   each. */\n"
    "const fast = {\n"
    "  frames: signal(0), packets: signal(0), gaps: signal(0), dupes: signal(0), torn: signal(0),\n"
    "  seconds: signal(0), rate: signal(0), loss: signal(0),\n"
    "  fSince: signal(0), fPolled: signal(-1), fSeen: signal(-1)\n"
    "};\n"
    "\n"
    "/* Measured progress per achievement and the value per tracked\n"
    "   leaderboard: one signal per id, created on first use. */\n"
    "const liveVals = new Map();\n"
    "function liveVal(id) {\n"
    "  if (!liveVals.has(id)) liveVals.set(id, signal({ m: '', p: 0 }));\n"
    "  return liveVals.get(id);\n"
    "}\n"
    "const trackVals = new Map();\n"
    "function trackVal(id) {\n"
    "  if (!trackVals.has(id)) trackVals.set(id, signal(''));\n"
    "  return trackVals.get(id);\n"
    "}\n"
    "\n"
    "/* What the page is listening to. The console has LIVE while it\n"
    "   streams; following takes over when it stops; otherwise idle. */\n"
    "const mode = computed(() => {\n"
    "  const s = S.state.value;\n"
    "  if (!s) return 'idle';\n"
    "  return s.console.connected ? 'console' : (s.follow || {}).active ? 'follow' : 'idle';\n"
    "});\n"
    "\n"
    "/* Snapshots per second, from the frame counter's own movement, and\n"
    "   the share of packets lost over the last few seconds. */\n"
    "const rateWin = { frames: 0, at: 0 };\n"
    "const lossWin = [];\n"
    "function measure(c) {\n"
    "  const now = performance.now();\n"
    "  const frames = c.frames || 0, gaps = c.gaps || 0;\n"
    "\n"
    "  if (!rateWin.at || frames < rateWin.frames) { rateWin.frames = frames; rateWin.at = now; fast.rate.value = 0; }\n"
    "  else if (now - rateWin.at >= 1000) {\n"
    "    fast.rate.value = Math.round((frames - rateWin.frames) * 1000 / (now - rateWin.at));\n"
    "    rateWin.frames = frames; rateWin.at = now;\n"
    "  }\n"
    "\n"
    "  lossWin.push({ at: now, frames, gaps });\n"
    "  while (lossWin.length && now - lossWin[0].at > 3000) lossWin.shift();\n"
    "  const a = lossWin[0], b = lossWin[lossWin.length - 1];\n"
    "  const df = b.frames - a.frames, dg = b.gaps - a.gaps;\n"
    "  fast.loss.value = df + dg > 0 && dg >= 0 ? Math.min(1, dg / (df + dg)) : 0;\n"
    "}\n"
    "\n"
    "function setFast(c) {\n"
    "  fast.frames.value = c.frames || 0;\n"
    "  fast.packets.value = c.packets || 0;\n"
    "  fast.gaps.value = c.gaps || 0;\n"
    "  fast.dupes.value = c.dupes || 0;\n"
    "  fast.torn.value = c.torn || 0;\n"
    "  fast.seconds.value = c.seconds || 0;\n"
    "  measure(c);\n"
    "}\n"
    "\n"
    "function setLive(list, trk) {\n"
    "  for (const a of list || []) {\n"
    "    const sig = liveVal(a.id), cur = sig.value;\n"
    "    const m = a.m != null ? a.m : (a.measured || ''), p = pctClamp(a.p != null ? a.p : a.percent);\n"
    "    if (cur.m !== m || cur.p !== p) sig.value = { m, p };\n"
    "  }\n"
    "  for (const tr of trk || []) {\n"
    "    const v = tr.v != null ? tr.v : tr.value;\n"
    "    const sig = trackVal(tr.id);\n"
    "    if (sig.value !== v) sig.value = v;\n"
    "  }\n"
    "}\n"
    "\n"
    "let lastUnlock = 0, wasConsole = false;\n"
    "\n"
    "/* Applies a full state: the counters, the live values, the follow\n"
    "   clocks, the state signal, the power-on trigger and the unlock toast. */\n"
    "function applyState(s) {\n"
    "  if (!s.game) s.game = { achievements: [] };\n"
    "  batch(() => {\n"
    "    const c = s.console || {};\n"
    "    const f = s.follow || {};\n"
    "\n"
    "    if (s.version) S.version.value = s.version;\n"
    "    setFast(c);\n"
    "    setLive(s.game.achievements, s.game.tracking);\n"
    "    if (f.active) {\n"
    "      fast.fSince.value = f.since || 0;\n"
    "      fast.fPolled.value = f.polled_ago >= 0 ? f.polled_ago : -1;\n"
    "      fast.fSeen.value = f.rp_ago >= 0 ? f.rp_ago : -1;\n"
    "    }\n"
    "    S.state.value = s;\n"
    "\n"
    "    /* connected went from false to true. */\n"
    "    if (c.connected && !wasConsole) S.powerOn.value++;\n"
    "    wasConsole = !!c.connected;\n"
    "\n"
    "    const u = s.unlocks && s.unlocks[0];\n"
    "    if (u && u.id !== lastUnlock && u.ago < 12) {\n"
    "      lastUnlock = u.id;\n"
    "      delete S.gameCache[s.game.id];\n"
    "      S.gameTick.value++;\n"
    "      /* The library is dropped and fetched again on the next visit. */\n"
    "      S.library.value = null;\n"
    "      S.toast.value = { id: u.id, title: u.title, badge: u.badge || '', points: u.points };\n"
    "      setTimeout(() => { if (S.toast.value && S.toast.value.id === u.id) S.toast.value = null; }, 6000);\n"
    "    }\n"
    "  });\n"
    "  if (s.game.id && S.liveMeta.value.id !== s.game.id) loadLiveMeta(s.game.id);\n"
    "}\n"
    "\n"
    "function applyDelta(d) {\n"
    "  batch(() => {\n"
    "    if (d.console) setFast(d.console);\n"
    "    setLive(d.live, d.tracking);\n"
    "  });\n"
    "}\n"
    "\n"
    "/* ==== 03-api.js ==== */\n"
    "/* ---- The client's endpoints -------------------------------------------- */\n"
    "\n"
    "async function getJSON(url) {\n"
    "  return (await fetch(url, { cache: 'no-store' })).json();\n"
    "}\n"
    "\n"
    "async function postForm(url, data) {\n"
    "  const r = await fetch(url, { method: 'POST', body: new URLSearchParams(data) });\n"
    "  return r.json();\n"
    "}\n"
    "\n"
    "async function refreshState() {\n"
    "  applyState(await getJSON('/state'));\n"
    "}\n"
    "\n"
    "/* /events: one full state or one delta per message. The browser\n"
    "   reconnects on its own; tick() polls /state every 2 s as well. */\n"
    "function stream() {\n"
    "  const es = new EventSource('/events');\n"
    "  es.onmessage = e => {\n"
    "    try {\n"
    "      const d = JSON.parse(e.data);\n"
    "      if (d.delta) applyDelta(d); else applyState(d);\n"
    "    } catch (err) { /* not JSON: skipped */ }\n"
    "  };\n"
    "}\n"
    "\n"
    "async function tick() {\n"
    "  try { await refreshState(); } catch (e) { /* keep polling */ }\n"
    "  setTimeout(tick, 2000);\n"
    "}\n"
    "\n"
    "function loadProfile() {\n"
    "  getJSON('/profile').then(p => { S.profile.value = p; }).catch(() => {});\n"
    "}\n"
    "\n"
    "/* Fetches /library unless a copy younger than two minutes is held. */\n"
    "let libraryLoading = false;\n"
    "async function loadLibrary() {\n"
    "  if (libraryLoading) return;\n"
    "  if (S.library.value && Date.now() - S.libraryAt < 120000) return;\n"
    "  libraryLoading = true;\n"
    "  try {\n"
    "    S.library.value = (await getJSON('/library')).games || [];\n"
    "    S.libraryAt = Date.now();\n"
    "  } catch (e) {\n"
    "    S.library.value = { error: true };\n"
    "  }\n"
    "  libraryLoading = false;\n"
    "}\n"
    "\n"
    "/* Fetches /game once per id into S.gameCache and bumps gameTick. */\n"
    "const gameLoading = new Set();\n"
    "async function loadGame(id) {\n"
    "  if (!id || S.gameCache[id] || gameLoading.has(id)) return;\n"
    "  gameLoading.add(id);\n"
    "  try {\n"
    "    S.gameCache[id] = await getJSON('/game?id=' + id);\n"
    "  } catch (e) {\n"
    "    S.gameCache[id] = { id, error: true, achievements: [] };\n"
    "  }\n"
    "  gameLoading.delete(id);\n"
    "  S.gameTick.value++;\n"
    "}\n"
    "\n"
    "async function loadBoards(id) {\n"
    "  if (!id || S.boardsCache[id]) return;\n"
    "  S.boardsCache[id] = { loading: true };\n"
    "  try {\n"
    "    S.boardsCache[id] = { boards: (await getJSON('/boards?id=' + id)).boards || [] };\n"
    "  } catch (e) {\n"
    "    S.boardsCache[id] = { error: true };\n"
    "  }\n"
    "  S.boardsTick.value++;\n"
    "}\n"
    "\n"
    "/* Fetches /game for the running game and keeps its medians and types\n"
    "   by id in S.liveMeta. The answer fills S.gameCache too. */\n"
    "let liveMetaLoading = false;\n"
    "function loadLiveMeta(id) {\n"
    "  if (liveMetaLoading || !id) return;\n"
    "  liveMetaLoading = true;\n"
    "  getJSON('/game?id=' + id).then(g => {\n"
    "    const byId = {};\n"
    "    for (const a of g.achievements || [])\n"
    "      byId[a.id] = { median: a.median || 0, type: a.type || '' };\n"
    "    S.gameCache[id] = g;\n"
    "    S.gameTick.value++;\n"
    "    S.liveMeta.value = { id, byId, icon: g.icon || '' };\n"
    "    liveMetaLoading = false;\n"
    "  }).catch(() => { liveMetaLoading = false; });\n"
    "}\n"
    "\n"
    "function openGame(id) {\n"
    "  S.gameId.value = id;\n"
    "  S.tab.value = 'game';\n"
    "}\n"
    "\n"
    "/* ==== 10-components.js ==== */\n"
    "/* ---- Shared components ------------------------------------------------- */\n"
    "\n"
    "/* Section label with a rule after it; `count` is an optional tail. */\n"
    "function Eyebrow({ children, count }) {\n"
    "  return html`<h2 class=\"eyebrow\">${children}${count != null && html`<span class=\"count\">${count}</span>`}</h2>`;\n"
    "}\n"
    "\n"
    "/* One stat tile. `v` may be a signal: the text then updates in place. */\n"
    "function Cell({ k, v, cls }) {\n"
    "  return html`<div class=\"cell\"><div class=\"k\">${k}</div><div class=${'v ' + (cls || '')}>${v}</div></div>`;\n"
    "}\n"
    "\n"
    "function Bar({ value, thin }) {\n"
    "  return html`<div class=${'bar' + (thin ? ' thin' : '')}><i style=${{ width: pctClamp(value) + '%' }} /></div>`;\n"
    "}\n"
    "\n"
    "/* Softcore and hardcore progress, one bar each. `labels` adds the\n"
    "   name and the count beside each bar. */\n"
    "function Bars({ awarded, hardcore, total, thin, labels }) {\n"
    "  const row = (cls, label, n) => html`<div class=\"prog\">\n"
    "    ${labels && html`<span class=\"k\">${label}</span>`}\n"
    "    <div class=${'bar ' + cls + (thin ? ' thin' : '')}><i style=${{ width: pct(n, total) + '%' }} /></div>\n"
    "    ${labels && html`<span class=\"n\">${n} / ${total}</span>`}\n"
    "  </div>`;\n"
    "  return html`<div class=\"bars\">${row('sc', t('SOFTCORE'), awarded || 0)}${row('hc', t('HARDCORE'), hardcore || 0)}</div>`;\n"
    "}\n"
    "\n"
    "/* Measured progress of one achievement, read from its live signal. */\n"
    "function Mini({ id }) {\n"
    "  const v = liveVal(id).value;\n"
    "  return v.p > 0 ? html`<div class=\"mini\"><i style=${{ width: v.p + '%' }} /></div>` : null;\n"
    "}\n"
    "\n"
    "function Measured({ id }) {\n"
    "  const v = liveVal(id).value;\n"
    "  return v.m ? html`<span class=\"lead acc\">${v.m}</span>` : null;\n"
    "}\n"
    "\n"
    "function Chip({ on, onClick, children, n, cls, title }) {\n"
    "  return html`<span class=${'chip' + (on ? ' on' : '') + (cls ? ' ' + cls : '')} onClick=${onClick} title=${title}>\n"
    "    ${children}${n != null && html` <span class=\"n\">${n}</span>`}</span>`;\n"
    "}\n"
    "\n"
    "function Empty({ children }) { return html`<div class=\"empty\">${children}</div>`; }\n"
    "\n"
    "/* Achievement row: badge, title, description, a right column of\n"
    "   lines. `state` picks the look: done, near, na, locked. */\n"
    "function AchRow({ a, state, big, right, below }) {\n"
    "  const locked = state !== 'done';\n"
    "  return html`<div class=${'row ' + state + (big ? ' big' : '')}>\n"
    "    <img class=\"badge\" src=${badgeUrl(a, locked)} alt=\"\" loading=\"lazy\" />\n"
    "    <div class=\"body\">\n"
    "      <div class=\"t\">${a.title}</div>\n"
    "      <div class=\"d\">${a.description}</div>\n"
    "      ${below}\n"
    "    </div>\n"
    "    <div class=\"m\">${right}</div>\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* Type tag for the right column: missable in amber, the rest muted. */\n"
    "function TypeTag({ a }) {\n"
    "  const ty = achType(a);\n"
    "  if (!ty) return null;\n"
    "  return html`<span class=${ty === 'missable' ? 'warn' : ''}>${t(ty.replace('_', ' '))}</span>`;\n"
    "}\n"
    "\n"
    "/* Points and the tags after them, one line. */\n"
    "function Pts({ a, extra }) {\n"
    "  const parts = [html`<span class=\"gold\">${t('{points} pts', { points: a.points })}</span>`];\n"
    "  const tag = achType(a);\n"
    "  if (tag) parts.push(html`<${TypeTag} a=${a} />`);\n"
    "  if (extra) parts.push(...(Array.isArray(extra) ? extra : [extra]));\n"
    "  return html`<span class=\"tag\">${parts.map((p, i) => html`${i ? ' · ' : ''}${p}`)}</span>`;\n"
    "}\n"
    "\n"
    "/* Labelled toggle; `busy` greys it while the client answers. */\n"
    "function Switch({ on, label, text, busy, onToggle }) {\n"
    "  return html`<div class=${'switch' + (on ? ' on' : '') + (busy ? ' busy' : '')} onClick=${onToggle}>\n"
    "    <span class=\"k\">${label}</span>\n"
    "    <span class=\"d\">${text}</span>\n"
    "    <span class=\"tog\" />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "function Btn({ children, onClick, primary, danger, sm, disabled, type, id }) {\n"
    "  const cls = 'btn' + (primary ? ' primary' : '') + (danger ? ' danger' : '') + (sm ? ' sm' : '');\n"
    "  return html`<button class=${cls} onClick=${onClick} disabled=${disabled} type=${type || 'button'} id=${id}>${children}</button>`;\n"
    "}\n"
    "\n"
    "/* The disc: the cover turned by a requestAnimationFrame loop. Speed\n"
    "   follows the snapshot rate; the loss share slows it; each new gap\n"
    "   knocks the speed down for a moment and lights the hole red. */\n"
    "function Disc({ src }) {\n"
    "  const face = useRef();\n"
    "  const disc = useRef();\n"
    "\n"
    "  useEffect(() => {\n"
    "    const still = matchMedia('(prefers-reduced-motion: reduce)').matches;\n"
    "    if (still) return undefined;\n"
    "    let angle = 0, last = performance.now(), raf = 0;\n"
    "    let gaps = fast.gaps.peek(), kick = 0, stalled = false;\n"
    "\n"
    "    const loop = now => {\n"
    "      const dt = Math.min(0.1, (now - last) / 1000);\n"
    "      last = now;\n"
    "\n"
    "      const g = fast.gaps.peek();\n"
    "      if (g > gaps) kick = Math.min(1, kick + 0.6);\n"
    "      gaps = g;\n"
    "      kick = Math.max(0, kick - dt * 1.6);\n"
    "\n"
    "      const rate = fast.rate.peek();\n"
    "      const base = rate > 0 ? 90 + rate * 3 : 25;\n"
    "      const speed = base * (1 - 0.75 * fast.loss.peek()) * (1 - 0.92 * kick);\n"
    "      angle = (angle + speed * dt) % 360;\n"
    "      if (face.current) face.current.style.transform = 'rotate(' + angle.toFixed(2) + 'deg)';\n"
    "\n"
    "      const stall = kick > 0.35;\n"
    "      if (stall !== stalled && disc.current) {\n"
    "        disc.current.classList.toggle('stall', stall);\n"
    "        stalled = stall;\n"
    "      }\n"
    "      raf = requestAnimationFrame(loop);\n"
    "    };\n"
    "    raf = requestAnimationFrame(loop);\n"
    "    return () => cancelAnimationFrame(raf);\n"
    "  }, []);\n"
    "\n"
    "  return html`<div class=\"disc\" ref=${disc}>\n"
    "    <div class=\"face\" ref=${face}>\n"
    "      ${src && html`<img src=${src} alt=\"\" />`}\n"
    "      <div class=\"iris\" /><div class=\"grooves\" />\n"
    "    </div>\n"
    "    <div class=\"sheen\" /><div class=\"rim\" /><div class=\"hole\" />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* The cover of the game on LIVE: a disc while the console streams, a\n"
    "   still cover with a signal ring while following, plain otherwise. */\n"
    "function Cover({ src }) {\n"
    "  const m = mode.value;\n"
    "  if (m === 'console') return html`<${Disc} src=${src} />`;\n"
    "  const img = src ? html`<img class=\"cover\" src=${src} alt=\"\" />` : html`<div class=\"cover\" />`;\n"
    "  if (m === 'follow') return html`<div class=\"cover-wrap\">${img}<div class=\"ring\" /></div>`;\n"
    "  return img;\n"
    "}\n"
    "\n"
    "function Toast() {\n"
    "  const u = S.toast.value;\n"
    "  if (!u) return null;\n"
    "  return html`<div class=\"toast\">\n"
    "    <img src=${BADGE + u.badge + '.png'} alt=\"\" />\n"
    "    <div>\n"
    "      <div class=\"k\">${t('ACHIEVEMENT UNLOCKED')}</div>\n"
    "      <div class=\"t\">${u.title}</div>\n"
    "      <div class=\"p\">${t('+{points} pts', { points: u.points })}</div>\n"
    "    </div>\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* One sweep of light, mounted for 1.3 s when the console connects. */\n"
    "function PowerOn() {\n"
    "  const n = S.powerOn.value;\n"
    "  const [shown, setShown] = useState(0);\n"
    "\n"
    "  useEffect(() => {\n"
    "    if (!n) return undefined;\n"
    "    setShown(n);\n"
    "    const id = setTimeout(() => setShown(0), 1300);\n"
    "    return () => clearTimeout(id);\n"
    "  }, [n]);\n"
    "  return shown ? html`<div class=\"poweron\" key=${shown} />` : null;\n"
    "}\n"
    "\n"
    "/* ==== 20-live.js ==== */\n"
    "/* ---- LIVE: the console's session, or the account's play elsewhere ------ */\n"
    "\n"
    "const STATUS = {\n"
    "  'active':         ['achievement set active, unlocks are tracked', 'ok'],\n"
    "  'no-hash':        [\"image not identified &mdash; run 'RA: check game support' in the game's OPL menu\", 'warn'],\n"
    "  'telemetry-only': ['telemetry only &mdash; no achievement set could be loaded for this image', 'warn'],\n"
    "  'identifying':    ['loading the achievement set for this image &mdash; a few seconds', 'warn'],\n"
    "  'stale':          [\"console watch list is out of date &mdash; run 'RA: check game support' again\", 'warn']\n"
    "};\n"
    "\n"
    "/* Frame counter with the rate, or the packet count before the first frame. */\n"
    "const framesText = computed(() => {\n"
    "  const fr = fast.frames.value, r = fast.rate.value;\n"
    "  return fr ? fr.toLocaleString() + (r ? ' · ' + r + '/s' : '')\n"
    "            : t('{packets} packets', { packets: fast.packets.value.toLocaleString() });\n"
    "});\n"
    "const sessionText = computed(() => fast.seconds.value ? hms(fast.seconds.value) : '—');\n"
    "const fSinceText = computed(() => fast.fSince.value ? hms(fast.fSince.value) : '—');\n"
    "const fPolledText = computed(() => fast.fPolled.value >= 0 ? agoText(fast.fPolled.value) : '—');\n"
    "\n"
    "/* FOLLOW MY PLAY: hidden on REMOTE and without a Web API key. Posts\n"
    "   /follow and fetches the state again. */\n"
    "function FollowSwitch({ s }) {\n"
    "  const [busy, setBusy] = useState(false);\n"
    "  const [err, setErr] = useState('');\n"
    "  const f = s.follow || {}, li = s.login || {};\n"
    "\n"
    "  if (REMOTE || !li.webapi) return null;\n"
    "  const text = err ? err\n"
    "    : s.console.connected ? t('the console has LIVE while it streams; following takes over when it stops')\n"
    "    : f.on ? t('LIVE shows the game you are in on any emulator with RetroAchievements, and the unlocks as they land')\n"
    "           : t('off. Turn it on and LIVE follows your account on any emulator with RetroAchievements');\n"
    "\n"
    "  const toggle = async () => {\n"
    "    setBusy(true); setErr('');\n"
    "    try {\n"
    "      const r = await postForm('/follow', { on: f.on ? '0' : '1' });\n"
    "      if (r.ok) await refreshState(); else setErr(r.error || t('failed'));\n"
    "    } catch (e) { setErr(t('could not reach the client')); }\n"
    "    setBusy(false);\n"
    "  };\n"
    "  return html`<${Switch} on=${!!f.on} label=${t('FOLLOW MY PLAY')} text=${text} busy=${busy} onToggle=${toggle} />`;\n"
    "}\n"
    "\n"
    "/* One line per counter in a tile: the string is split on its dots. */\n"
    "function lines(text) {\n"
    "  return text.split(' \\u00b7 ').map((p, i) => html`${i ? html`<br />` : ''}${p}`);\n"
    "}\n"
    "\n"
    "/* The three loss counters; the component redraws when any one moves. */\n"
    "function Lost() {\n"
    "  return lines(t('{gaps} skipped \\u00b7 {dupes} repeated \\u00b7 {torn} torn',\n"
    "                 { gaps: fast.gaps.value, dupes: fast.dupes.value, torn: fast.torn.value }));\n"
    "}\n"
    "\n"
    "/* Sends the console back to the loader menu: the in-game reset, from\n"
    "   the PC instead of the six-button combo. Local only, like QUIT. */\n"
    "async function resetConsole() {\n"
    "  if (!confirm(t('Close the game and return the console to the loader menu?'))) return;\n"
    "  try {\n"
    "    const r = await postForm('/reset', {});\n"
    "    if (r && r.ok === false) alert(t('The console has not been seen yet.'));\n"
    "  } catch (err) { alert(t('The client did not answer.')); }\n"
    "}\n"
    "\n"
    "/* CONSOLE panel: link, serial, counters, watch list, session clock. */\n"
    "function ConsolePanel({ s }) {\n"
    "  const c = s.console;\n"
    "  if (!c.connected && !c.packets) return null;\n"
    "  if (!c.connected && (s.follow || {}).active) return null;\n"
    "\n"
    "  const st = STATUS[c.status];\n"
    "  const w = c.watch || {};\n"
    "  const watch = w.addresses\n"
    "    ? lines(t('{addresses} addr &middot; {bytes} B &middot; {parts} parts',\n"
    "              { addresses: w.addresses, bytes: w.bytes, parts: w.parts }))\n"
    "    : '—';\n"
    "\n"
    "  return html`<${Fragment}>\n"
    "    <${Eyebrow}>${t('CONSOLE')}<//>\n"
    "    ${st && html`<div class=${'banner ' + st[1]}>${t(st[0])}</div>`}\n"
    "    <div class=\"stats\">\n"
    "      <${Cell} k=${t('LINK')} v=${c.connected ? c.ip : html`<span class=\"mute\">${t('lost')}</span>`} />\n"
    "      <${Cell} k=${t('GAME')} v=${s.game.serial || '—'} />\n"
    "      <${Cell} k=${t('SNAPSHOTS')} v=${framesText} />\n"
    "      <${Cell} k=${t('LOST')} v=${html`<${Lost} />`} />\n"
    "      <${Cell} k=${t('WATCH LIST')} v=${watch} />\n"
    "      <${Cell} k=${t('SESSION')} v=${sessionText} />\n"
    "    </div>\n"
    "    ${s.game.hash && html`<div class=\"hash\">${t('hash {hash}', { hash: s.game.hash })}</div>`}\n"
    "    ${!REMOTE && c.connected && html`<div class=\"subsets\"><${Btn} danger sm onClick=${resetConsole}>${t('RESET CONSOLE')}<//></div>`}\n"
    "  <//>`;\n"
    "}\n"
    "\n"
    "/* FOLLOWING panel: the rich presence line, the poll, this session's unlocks. */\n"
    "function FollowPanel({ s }) {\n"
    "  const f = s.follow;\n"
    "  if (!f || !f.active) return null;\n"
    "  const seen = f.online ? html`<span class=\"ok\">${t('playing now')}</span>`\n"
    "             : f.rp_date ? f.rp_date\n"
    "             : fast.fSeen.value >= 0 ? agoText(fast.fSeen.value) : '—';\n"
    "  const session = f.session || [];\n"
    "\n"
    "  return html`<${Fragment}>\n"
    "    <${Eyebrow}>${t('FOLLOWING')}<//>\n"
    "    <div class=\"banner ok\">${f.rp ? f.rp : t('no rich presence line yet')}</div>\n"
    "    <div class=\"stats\">\n"
    "      <${Cell} k=${t('PLATFORM')} v=${s.game.console || '—'} />\n"
    "      <${Cell} k=${t('LAST SEEN')} v=${seen} />\n"
    "      <${Cell} k=${t('SOURCE')} v=${t('RetroAchievements &middot; every 20 s')} />\n"
    "      <${Cell} k=${t('POLLED')} v=${fPolledText} />\n"
    "      <${Cell} k=${t('SESSION')} v=${fSinceText} />\n"
    "      <${Cell} k=${t('UNLOCKS')} v=${session.length} />\n"
    "    </div>\n"
    "    ${f.failures ? html`<div class=\"note warn\">${t('the Web API is not answering; retrying')}</div>` : null}\n"
    "    ${session.length > 0 && html`<${Eyebrow}>${t('THIS SESSION')}<//>\n"
    "      ${session.map(u => html`<div class=\"row done\" key=${u.id}>\n"
    "        <img class=\"badge\" src=${BADGE + u.badge + '.png'} alt=\"\" />\n"
    "        <div class=\"body\"><div class=\"t\">${u.title}</div>\n"
    "          <div class=\"d\">${agoText(u.ago)}${u.hardcore ? ' · ' + t('hardcore') : ''}</div></div>\n"
    "        <div class=\"m\"><span class=\"lead ok\">+${u.points}</span></div>\n"
    "      </div>`)}`}\n"
    "  <//>`;\n"
    "}\n"
    "\n"
    "/* The game's head: cover, title, progress bar, counts. */\n"
    "function LiveHead({ s, list, done, ptsDone, ptsAll, icon }) {\n"
    "  return html`<div class=\"head\">\n"
    "    <${Cover} src=${icon ? MEDIA + icon : ''} />\n"
    "    <div class=\"body\">\n"
    "      <h1>${s.game.title || s.game.serial}</h1>\n"
    "      <${Bar} value=${pct(done, list.length)} />\n"
    "      <div class=\"sub\">\n"
    "        <span>${s.game.checked_only ? t('from an image check, not from a running game') : (s.game.serial || s.game.console || '')}</span>\n"
    "        <span class=\"right\"><b>${done}</b> / ${list.length} <span class=\"mute\">·</span> <span class=\"gold\">${ptsDone}</span><span class=\"mute\"> / ${t('{points} pts', { points: ptsAll })}</span></span>\n"
    "      </div>\n"
    "    </div>\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* ALL ACHIEVEMENTS: one list, or one per subset when there are several. */\n"
    "function AchievementGroups({ list, subsets, row }) {\n"
    "  if (!subsets || subsets.length < 2) return list.map(row);\n"
    "  return subsets.map(sub => {\n"
    "    const mine = list.filter(a => a.subset === sub.id);\n"
    "    if (!mine.length) return null;\n"
    "    const done = mine.filter(a => a.state === 2).length;\n"
    "    return html`<${Fragment} key=${sub.id}>\n"
    "      <${Eyebrow} count=${done + ' / ' + mine.length}>${sub.title.toUpperCase()}<//>\n"
    "      ${mine.map(row)}\n"
    "    <//>`;\n"
    "  });\n"
    "}\n"
    "\n"
    "/* One row of ALL ACHIEVEMENTS; reads the achievement's live signal for\n"
    "   the measured value and the progress. */\n"
    "function LiveRow({ a, missed, hidden }) {\n"
    "  const isDone = a.state === 2;\n"
    "  /* state 3 is rc_client's disabled state: 'not on hardware'. */\n"
    "  const na = a.state === 3;\n"
    "  const lv = liveVal(a.id).value;\n"
    "  const near = !isDone && !na && lv.p > 0;\n"
    "  const state = isDone ? 'done' : na ? 'na' : near ? 'near' : 'locked';\n"
    "  return html`<${AchRow} a=${a} state=${state}\n"
    "    below=${!isDone && !na && html`<${Mini} id=${a.id} />`}\n"
    "    right=${html`<${Fragment}>\n"
    "      ${isDone ? html`<span class=\"lead ok\">${t('unlocked')}</span>`\n"
    "        : na ? html`<span class=\"lead warn\">${t('not on hardware')}</span>`\n"
    "        : lv.m ? html`<span class=\"lead acc\">${lv.m}</span>`\n"
    "        : html`<span class=\"lead\">${t('locked')}</span>`}\n"
    "      <${Pts} a=${a} extra=${hidden ? html`<span class=\"mute\">${t('hidden')}</span>`\n"
    "                               : missed ? html`<span class=\"warn\">${t('possibly skipped')}</span>` : null} />\n"
    "    <//>`} />`;\n"
    "}\n"
    "\n"
    "function LiveTab() {\n"
    "  const s = S.state.value;\n"
    "  if (!s) return html`<${Empty}>${t('loading...')}<//>`;\n"
    "\n"
    "  const list = s.game.achievements || [];\n"
    "  const f = s.follow || {};\n"
    "\n"
    "  if (!list.length) {\n"
    "    return html`<div class=\"tab\">\n"
    "      <${FollowSwitch} s=${s} /><${ConsolePanel} s=${s} />\n"
    "      <${Empty}>${s.console.connected\n"
    "        ? t('console connected, waiting for a game with achievements')\n"
    "        : f.on && (s.login || {}).webapi\n"
    "          ? t('following your RetroAchievements activity: start a game on the console, or in any emulator with RetroAchievements on, and it shows up here within half a minute')\n"
    "          : t('start a game on the console, or browse your library above')}<//>\n"
    "    </div>`;\n"
    "  }\n"
    "\n"
    "  const done = list.filter(a => a.state === 2).length;\n"
    "  const ptsDone = list.filter(a => a.state === 2).reduce((n, a) => n + (a.points || 0), 0);\n"
    "  const ptsAll = list.reduce((n, a) => n + (a.points || 0), 0);\n"
    "\n"
    "  const lm = S.liveMeta.value;\n"
    "  const meta = lm.id === s.game.id ? lm.byId : null;\n"
    "  const medOf = a => meta ? ((meta[a.id] || {}).median || 0) : 0;\n"
    "  const missed = meta ? possiblyMissed(list, medOf) : new Set();\n"
    "  const position = meta ? Math.max(0, ...list.filter(a => a.state === 2).map(medOf)) : 0;\n"
    "  const est = meta ? setEstimates(list, medOf) : null;\n"
    "\n"
    "  /* UP NEXT: the nearest locked achievements by median, drawn big.\n"
    "     Hidden ones are left out and the next median takes the slot; the\n"
    "     chip in the label brings them all back. */\n"
    "  const hidden = new Set(S.hidden.value[s.game.id] || []);\n"
    "  let ahead = null;\n"
    "  if (meta) {\n"
    "    const picked = upNextPick(list.filter(a => !hidden.has(a.id)), medOf);\n"
    "    const restore = hidden.size > 0\n"
    "      ? html`<span class=\"chip sm\" onClick=${() => showHidden(s.game.id)}>${t('{n} hidden', { n: hidden.size })} · ${t('SHOW ALL')}</span>`\n"
    "      : null;\n"
    "    if (picked.next.length || restore) {\n"
    "      ahead = html`<${Eyebrow} count=${restore}>${t('UP NEXT &middot; BY MEDIAN UNLOCK TIME')}<//>\n"
    "        ${picked.next.map(a => html`<${AchRow} key=${a.id} a=${a} state=\"near\" big\n"
    "          below=${html`<${Mini} id=${a.id} />`}\n"
    "          right=${html`<${Fragment}>\n"
    "            <${Measured} id=${a.id} />\n"
    "            ${a === picked.prog && html`<span class=\"tag acc\">${t('next in progression')}</span>`}\n"
    "            ${missed.has(a.id) ? html`<span class=\"tag warn\">${t('possibly skipped')}</span>`\n"
    "              : medOf(a) <= position ? html`<span class=\"tag warn\">${t('usually done by now')}</span>` : null}\n"
    "            <${Pts} a=${a} extra=${'~' + medianText(medOf(a))} />\n"
    "            <span class=\"hide\" onClick=${() => hideAch(s.game.id, a.id)} title=${t('hide from UP NEXT')}>✕ ${t('HIDE')}</span>\n"
    "          <//>`} />`)}`;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  const trackers = (s.game.tracking || []).length\n"
    "    ? html`<${Eyebrow}>${t('TRACKING NOW')}<//>\n"
    "        ${s.game.tracking.map(tr => html`<div class=\"row near\" key=${tr.id}>\n"
    "          <div class=\"body\"><div class=\"t\">${tr.title}</div></div>\n"
    "          <div class=\"m\"><span class=\"lead acc\">${trackVal(tr.id)}</span></div>\n"
    "        </div>`)}`\n"
    "    : null;\n"
    "\n"
    "  const strip = html`<div class=\"stats\">\n"
    "    <${Cell} k=${t('ACHIEVEMENTS')} v=${done + ' / ' + list.length} />\n"
    "    <${Cell} k=${t('POINTS')} v=${html`<span class=\"gold\">${ptsDone}</span> / ${ptsAll}`} />\n"
    "    <${Cell} k=${t('BEATEN AT')} v=${est && est.beaten ? '~' + medianText(est.beaten) : '—'} />\n"
    "    <${Cell} k=${t('FULL SET AT')} v=${est && est.full ? '~' + medianText(est.full) : '—'} />\n"
    "    <${Cell} k=${t('YOUR POSITION')} v=${position ? '~' + medianText(position) : '—'} />\n"
    "    <${Cell} k=${t('MISSABLES LEFT')} v=${list.filter(a => a.state !== 2 && achType(a) === 'missable').length} />\n"
    "  </div>`;\n"
    "\n"
    "  const row = a => html`<${LiveRow} key=${a.id} a=${a} missed=${missed.has(a.id)} hidden=${hidden.has(a.id)} />`;\n"
    "\n"
    "  const showAll = ahead || trackers || (s.game.subsets || []).length > 1;\n"
    "\n"
    "  return html`<div class=\"tab\">\n"
    "    <${FollowSwitch} s=${s} />\n"
    "    <${FollowPanel} s=${s} />\n"
    "    <${ConsolePanel} s=${s} />\n"
    "    <${LiveHead} s=${s} list=${list} done=${done} ptsDone=${ptsDone} ptsAll=${ptsAll}\n"
    "      icon=${(meta && lm.icon) || s.game.icon || ''} />\n"
    "    ${strip}\n"
    "    ${ahead}\n"
    "    ${trackers}\n"
    "    ${showAll && html`<${Eyebrow} count=${done + ' / ' + list.length}>${t('ALL ACHIEVEMENTS')}<//>`}\n"
    "    <${AchievementGroups} list=${list} subsets=${s.game.subsets} row=${row} />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* ==== 21-library.js ==== */\n"
    "/* ---- LIBRARY: every game the account touched, from the Web API --------- */\n"
    "\n"
    "/* HighestAwardKind: mastered and completed are the hardcore and softcore\n"
    "   full clears; beaten comes in the same two flavours. */\n"
    "function awardBadge(g) {\n"
    "  const a = g.award || '';\n"
    "  if (a === 'mastered') return html`<span class=\"award gold\">${t('MASTERED')}</span>`;\n"
    "  if (a === 'completed') return html`<span class=\"award green\">${t('COMPLETED · SC')}</span>`;\n"
    "  if (a === 'beaten-hardcore') return html`<span class=\"award blue\">${t('BEATEN')}</span>`;\n"
    "  if (a === 'beaten-softcore') return html`<span class=\"award blue\">${t('BEATEN · SC')}</span>`;\n"
    "  return null;\n"
    "}\n"
    "\n"
    "/* A card: the award sits in the corner of the art, the console always\n"
    "   shows in the foot, two bars for softcore and hardcore. */\n"
    "function GameCard({ g }) {\n"
    "  const art = g.icon ? MEDIA + g.icon : '';\n"
    "  const award = awardBadge(g);\n"
    "  return html`<div class=\"card\" onClick=${() => openGame(g.id)}>\n"
    "    <div class=\"art\">\n"
    "      ${art && html`<div class=\"blur\" style=${{ backgroundImage: 'url(' + art + ')' }} />`}\n"
    "      ${art && html`<img src=${art} loading=\"lazy\" alt=\"\" onError=${e => e.target.remove()} />`}\n"
    "      ${award && html`<span class=\"corner\">${award}</span>`}\n"
    "    </div>\n"
    "    <div class=\"meta\">\n"
    "      <div class=\"name\">${g.title}</div>\n"
    "      <${Bars} awarded=${g.awarded} hardcore=${g.hardcore} total=${g.total} thin />\n"
    "      <div class=\"foot\">\n"
    "        <span>${g.awarded} / ${g.total}${g.hardcore > 0\n"
    "          ? html` <span class=\"gold\">${t('({n} hc)', { n: g.hardcore })}</span>` : ''}</span>\n"
    "        <span class=\"right mute\">${g.console}</span>\n"
    "      </div>\n"
    "    </div>\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "const LIB_FILTERS = [['all', 'ALL {n}'], ['new', 'NOT STARTED'], ['progress', 'IN PROGRESS'],\n"
    "                     ['beaten', 'BEATEN'], ['mastered', 'MASTERED']];\n"
    "\n"
    "function LibraryTab() {\n"
    "  useEffect(() => { loadLibrary(); }, []);\n"
    "  const library = S.library.value;\n"
    "\n"
    "  if (!library) return html`<div class=\"tab\"><${Empty}>${t('loading your library...')}<//></div>`;\n"
    "  if (library.error) return html`<div class=\"tab\"><${Empty}>${t('could not reach the client')}<//></div>`;\n"
    "\n"
    "  const filter = S.libFilter.value;\n"
    "  const consoles = S.libConsoles.value;\n"
    "  const open = S.libConsolesOpen.value;\n"
    "\n"
    "  const isMastered = g => g.mastered || (g.total > 0 && g.awarded >= g.total);\n"
    "  const shown = library.filter(g => {\n"
    "    const ok =\n"
    "      filter === 'all' ? true :\n"
    "      filter === 'new' ? g.awarded === 0 :\n"
    "      filter === 'progress' ? g.awarded > 0 && g.awarded < g.total && !(g.award || '').startsWith('beaten') :\n"
    "      filter === 'beaten' ? (g.award || '').startsWith('beaten') :\n"
    "      isMastered(g);\n"
    "    return ok && (consoles.size === 0 || consoles.has(g.console));\n"
    "  });\n"
    "\n"
    "  /* Console chips: several can be on; an empty set means all. */\n"
    "  const perConsole = {};\n"
    "  for (const g of library) perConsole[g.console] = (perConsole[g.console] || 0) + 1;\n"
    "  const names = Object.keys(perConsole).sort();\n"
    "  const conLabel = consoles.size === 0 ? t('ALL CONSOLES')\n"
    "    : t(consoles.size > 1 ? '{n} CONSOLES' : '{n} CONSOLE', { n: consoles.size });\n"
    "  const toggleConsole = c => {\n"
    "    const next = new Set(consoles);\n"
    "    next.has(c) ? next.delete(c) : next.add(c);\n"
    "    S.libConsoles.value = next;\n"
    "  };\n"
    "\n"
    "  return html`<div class=\"tab\">\n"
    "    <div class=\"filters\">\n"
    "      ${LIB_FILTERS.map(([k, label]) => html`<${Chip} key=${k} on=${filter === k}\n"
    "        onClick=${() => { S.libFilter.value = k; }}>${t(label, { n: library.length })}<//>`)}\n"
    "      <${Chip} on=${consoles.size > 0} onClick=${() => { S.libConsolesOpen.value = !open; }}>\n"
    "        ${conLabel} ${open ? '▴' : '▾'}<//>\n"
    "    </div>\n"
    "    ${open && html`<div class=\"filters\">\n"
    "      ${names.map(c => html`<${Chip} key=${c} on=${consoles.has(c)} n=${perConsole[c]}\n"
    "        onClick=${() => toggleConsole(c)}>${c.toUpperCase()}<//>`)}\n"
    "    </div>`}\n"
    "    <div class=\"grid\">${shown.map(g => html`<${GameCard} key=${g.id} g=${g} />`)}</div>\n"
    "    ${!shown.length && html`<${Empty}>${t('nothing matches these filters')}<//>`}\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* ==== 22-game.js ==== */\n"
    "/* ---- GAME: one set in full, from the Web API --------------------------- */\n"
    "\n"
    "const GAME_FILTERS = [['all', 'ALL'], ['locked', 'LOCKED'], ['unlocked', 'UNLOCKED'],\n"
    "                      ['missable', 'MISSABLE'], ['progression', 'PROGRESSION'],\n"
    "                      ['win_condition', 'WIN CONDITION']];\n"
    "const GAME_SORTS = [['author', 'AUTHOR ORDER'], ['type', 'PROGRESSION PATH'], ['median', 'MEDIAN TIME']];\n"
    "\n"
    "/* The base game and its subsets as chips, the open one lit. A click\n"
    "   opens that game id. */\n"
    "function Family({ g }) {\n"
    "  if (!(g.subsets || []).length) return null;\n"
    "  const base = g.base || {};\n"
    "  return html`<div class=\"subsets\">\n"
    "    ${base.id > 0 && html`<${Chip} on=${base.id === g.id} onClick=${() => openGame(base.id)}>${t('MAIN SET')}<//>`}\n"
    "    ${g.subsets.map(sub => html`<${Chip} key=${sub.id} on=${sub.id === g.id} n=${sub.achievements}\n"
    "      onClick=${() => openGame(sub.id)}>${sub.title.toUpperCase()}<//>`)}\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* \"loading...\" for the first 12 s, then a note that the client is busy\n"
    "   and a link that clears the cache entry and fetches again. */\n"
    "function Loading({ id }) {\n"
    "  const [slow, setSlow] = useState(false);\n"
    "  useEffect(() => {\n"
    "    setSlow(false);\n"
    "    const tm = setTimeout(() => setSlow(true), 12000);\n"
    "    return () => clearTimeout(tm);\n"
    "  }, [id]);\n"
    "  if (!slow) return html`<${Empty}>${t('loading...')}<//>`;\n"
    "  return html`<${Empty}>${t('still loading; the client is busy with RetroAchievements')}${' '}\n"
    "    <a href=\"#\" onClick=${e => { e.preventDefault(); delete S.gameCache[id]; loadGame(id); }}>${t('try again')}</a><//>`;\n"
    "}\n"
    "\n"
    "function GameTab() {\n"
    "  const id = S.gameId.value;\n"
    "  S.gameTick.value; /* re-render when a fetch lands */\n"
    "  useEffect(() => { loadGame(id); loadLibrary(); }, [id]);\n"
    "  /* The award and the hardcore count come from the library entry:\n"
    "     /game has neither. */\n"
    "  const lib = (Array.isArray(S.library.value) ? S.library.value : []).find(x => x.id === id);\n"
    "\n"
    "  if (!id) return html`<div class=\"tab\"><${Empty}>${t('pick a game in the library')}<//></div>`;\n"
    "  const g = S.gameCache[id];\n"
    "  if (!g) return html`<div class=\"tab\"><${Loading} id=${id} /></div>`;\n"
    "  if (g.error) return html`<div class=\"tab\"><${Empty}>${t('could not reach the client')}<//></div>`;\n"
    "\n"
    "  const sort = S.gameSort.value, filter = S.gameFilter.value;\n"
    "  const all = g.achievements || [];\n"
    "  const list = sortAchievements(all.filter(a =>\n"
    "    filter === 'all' ? true :\n"
    "    filter === 'locked' ? !a.earned :\n"
    "    filter === 'unlocked' ? !!a.earned :\n"
    "    achType(a) === filter), sort);\n"
    "  const est = setEstimates(all, a => a.median || 0);\n"
    "\n"
    "  return html`<div class=\"tab\">\n"
    "    <div class=\"head\">\n"
    "      ${g.icon ? html`<img class=\"cover\" src=${MEDIA + g.icon} alt=\"\" />` : html`<div class=\"cover\" />`}\n"
    "      <div class=\"body\">\n"
    "        <h1>${g.title}${lib && awardBadge(lib) && html` <span class=\"h1-award\">${awardBadge(lib)}</span>`}</h1>\n"
    "        <div class=\"note\" style=${{ marginBottom: '10px' }}>\n"
    "          ${g.console} · ${t('{n} achievements', { n: all.length })}\n"
    "          ${est.full > 0 && html` · <span class=\"acc\">${est.beaten > 0 && t('beaten ~{time}', { time: medianText(est.beaten) }) + ' · '}${t('full set ~{time}', { time: medianText(est.full) })}</span> <span class=\"mute\">${t('by median unlocks')}</span>`}\n"
    "        </div>\n"
    "        <${Bars} labels awarded=${g.awarded} hardcore=${lib ? lib.hardcore : 0} total=${g.total} />\n"
    "        <div class=\"sub\">\n"
    "          <a href=${'https://retroachievements.org/game/' + g.id} target=\"_blank\" rel=\"noopener\">${t('on retroachievements.org')}</a>\n"
    "        </div>\n"
    "      </div>\n"
    "    </div>\n"
    "    <${Family} g=${g} />\n"
    "    <div class=\"filters\">\n"
    "      ${GAME_FILTERS.map(([k, label]) => html`<${Chip} key=${k} on=${filter === k}\n"
    "        onClick=${() => { S.gameFilter.value = k; }}>${t(label)}<//>`)}\n"
    "    </div>\n"
    "    <div class=\"filters\">\n"
    "      ${GAME_SORTS.map(([k, label]) => html`<${Chip} key=${k} on=${sort === k}\n"
    "        onClick=${() => { S.gameSort.value = k; }}>${t(label)}<//>`)}\n"
    "    </div>\n"
    "    ${list.map(a => html`<${AchRow} key=${a.id} a=${a} state=${a.earned ? 'done' : 'locked'}\n"
    "      right=${html`<${Fragment}>\n"
    "        ${a.earned ? html`<span class=\"lead ok\">${a.earned.slice(0, 10)}</span>`\n"
    "                   : html`<span class=\"lead\">${t('locked')}</span>`}\n"
    "        <${Pts} a=${a} extra=${a.median > 0 ? '~' + medianText(a.median) : null} />\n"
    "      <//>`} />`)}\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* ==== 23-boards.js ==== */\n"
    "/* ---- BOARDS: leaderboards, with the live trackers on top --------------- */\n"
    "\n"
    "function BoardsTab() {\n"
    "  const id = S.gameId.value;\n"
    "  S.boardsTick.value; /* re-render when a fetch lands */\n"
    "  useEffect(() => { loadBoards(id); }, [id]);\n"
    "\n"
    "  if (!id) return html`<div class=\"tab\"><${Empty}>${t('pick a game in the library')}<//></div>`;\n"
    "  const b = S.boardsCache[id];\n"
    "  if (!b || b.loading) return html`<div class=\"tab\"><${Empty}>${t('loading...')}<//></div>`;\n"
    "  if (b.error) return html`<div class=\"tab\"><${Empty}>${t('could not reach the client')}<//></div>`;\n"
    "\n"
    "  const s = S.state.value;\n"
    "  const tracking = (s && s.game.tracking) || [];\n"
    "  const open = S.openBoards.value;\n"
    "  const toggle = bid => {\n"
    "    const next = new Set(open);\n"
    "    next.has(bid) ? next.delete(bid) : next.add(bid);\n"
    "    S.openBoards.value = next;\n"
    "  };\n"
    "\n"
    "  return html`<div class=\"tab\">\n"
    "    ${tracking.length > 0 && html`<${Eyebrow}>${t('TRACKING NOW &middot; FROM CONSOLE MEMORY')}<//>\n"
    "      ${tracking.map(tr => html`<div class=\"row near\" key=${tr.id}>\n"
    "        <div class=\"body\"><div class=\"t\">${tr.title}</div></div>\n"
    "        <div class=\"m\"><span class=\"lead acc\">${trackVal(tr.id)}</span></div>\n"
    "      </div>`)}`}\n"
    "    <${Eyebrow}>${t('{n} LEADERBOARDS &middot; CLICK ONE TO EXPAND', { n: b.boards.length })}<//>\n"
    "    ${b.boards.map(bd => {\n"
    "      const isOpen = open.has(bd.id);\n"
    "      return html`<div class=${'row clickable' + (isOpen ? ' near' : '')} key=${bd.id} onClick=${() => toggle(bd.id)}>\n"
    "        <div class=\"body\">\n"
    "          <div class=\"t\">${isOpen ? '▾ ' : '▸ '}${bd.title}</div>\n"
    "          ${isOpen && html`<div class=\"d\">${bd.description}</div>`}\n"
    "        </div>\n"
    "        <div class=\"m\">\n"
    "          ${bd.topScore ? html`<span class=\"lead acc\">${bd.topScore}</span>${isOpen && html`<span class=\"tag\">${bd.topUser}</span>`}`\n"
    "                        : html`<span>${t('no entries')}</span>`}\n"
    "        </div>\n"
    "      </div>`;\n"
    "    })}\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* ==== 24-settings.js ==== */\n"
    "/* ---- SETTINGS: account, Web API key, the network switch ---------------- */\n"
    "\n"
    "/* The tab re-renders on this key: the login and the network setting,\n"
    "   not the whole state. */\n"
    "const settingsKey = computed(() => {\n"
    "  const s = S.state.value;\n"
    "  if (!s) return '';\n"
    "  const li = s.login || {}, lan = s.lan || {};\n"
    "  return [li.ok, li.user, li.webapi, lan.on, lan.url].join('|');\n"
    "});\n"
    "\n"
    "function Msg({ text, good }) {\n"
    "  return html`<div class=${'msg ' + (good ? 'ok' : 'warn')}>${text}</div>`;\n"
    "}\n"
    "\n"
    "function AccountBlock({ li }) {\n"
    "  const [msg, setMsg] = useState(['', true]);\n"
    "  const [busy, setBusy] = useState(false);\n"
    "\n"
    "  const signIn = async e => {\n"
    "    e.preventDefault();\n"
    "    const form = e.target;\n"
    "    setBusy(true); setMsg([t('signing in...'), true]);\n"
    "    try {\n"
    "      const r = await postForm('/login', { user: form.user.value.trim(), password: form.password.value });\n"
    "      if (r.ok) { setMsg(['', true]); await refreshState(); }\n"
    "      else setMsg([r.error || t('failed'), false]);\n"
    "    } catch (err) { setMsg([t('could not reach the client'), false]); }\n"
    "    setBusy(false);\n"
    "  };\n"
    "  const signOut = async () => {\n"
    "    try { await postForm('/logout', {}); } catch (err) { /* gone already */ }\n"
    "    try { await refreshState(); } catch (err) { /* the poll catches up */ }\n"
    "  };\n"
    "\n"
    "  return html`<div class=\"block\">\n"
    "    <${Eyebrow}>${t('RETROACHIEVEMENTS ACCOUNT')}<//>\n"
    "    ${li.ok\n"
    "      ? html`<div>${tv('signed in as {user}', { user: html`<span class=\"ok\">${li.user}</span>` })}</div>\n"
    "          <div class=\"note\">${t('unlocks from the console are credited to this account')}</div>\n"
    "          <${Btn} onClick=${signOut}>${t('SIGN OUT')}<//>`\n"
    "      : html`<div class=\"note\">${t('the account your unlocks are credited to; only a login token is stored')}</div>\n"
    "          <form onSubmit=${signIn}>\n"
    "            <label>${t('username')}</label><input class=\"f\" name=\"user\" autocomplete=\"username\" />\n"
    "            <label>${t('password')}</label><input class=\"f\" name=\"password\" type=\"password\" autocomplete=\"current-password\" />\n"
    "            <${Btn} type=\"submit\" primary disabled=${busy}>${t('SIGN IN')}<//>\n"
    "          </form>`}\n"
    "    <${Msg} text=${msg[0]} good=${msg[1]} />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "function KeyBlock({ li }) {\n"
    "  const [msg, setMsg] = useState(['', true]);\n"
    "  const [busy, setBusy] = useState(false);\n"
    "\n"
    "  const save = async e => {\n"
    "    e.preventDefault();\n"
    "    const form = e.target;\n"
    "    setBusy(true); setMsg([t('saving...'), true]);\n"
    "    try {\n"
    "      const r = await postForm('/apikey', { key: form.key.value.trim() });\n"
    "      if (r.ok) {\n"
    "        form.key.value = '';\n"
    "        S.library.value = null;\n"
    "        loadProfile();\n"
    "        await refreshState();\n"
    "        setMsg([t('saved'), true]);\n"
    "      } else setMsg([r.error || t('failed'), false]);\n"
    "    } catch (err) { setMsg([t('could not reach the client'), false]); }\n"
    "    setBusy(false);\n"
    "  };\n"
    "\n"
    "  return html`<div class=\"block\">\n"
    "    <${Eyebrow}>${t('WEB API KEY')}<//>\n"
    "    <div class=\"note\">${tv('a read-only key that fills the library, leaderboards and profile. Get it at {link}, section \"Keys\", and paste it here.',\n"
    "      { link: html`<a href=\"https://retroachievements.org/settings\" target=\"_blank\" rel=\"noopener\">retroachievements.org/settings</a>` })}</div>\n"
    "    <form onSubmit=${save}>\n"
    "      <label>${t('key')} ${li.webapi && html`<span class=\"ok\">${t('(saved, paste to replace)')}</span>`}</label>\n"
    "      <input class=\"f\" name=\"key\" autocomplete=\"off\" />\n"
    "      <${Btn} type=\"submit\" primary disabled=${busy}>${t('SAVE KEY')}<//>\n"
    "    </form>\n"
    "    <${Msg} text=${msg[0]} good=${msg[1]} />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "function LanBlock({ lan }) {\n"
    "  const [msg, setMsg] = useState(['', true]);\n"
    "  const [busy, setBusy] = useState(false);\n"
    "\n"
    "  const flip = async () => {\n"
    "    setBusy(true); setMsg([t(lan.on ? 'closing...' : 'opening...'), true]);\n"
    "    try {\n"
    "      const r = await postForm('/lan', { on: lan.on ? '0' : '1' });\n"
    "      if (!r.ok) { setMsg([r.error || t('failed'), false]); setBusy(false); return; }\n"
    "      /* The listener reopens on the next request. */\n"
    "      await new Promise(res => setTimeout(res, 700));\n"
    "      await refreshState();\n"
    "      setMsg(['', true]);\n"
    "    } catch (err) { setMsg([t('could not reach the client'), false]); }\n"
    "    setBusy(false);\n"
    "  };\n"
    "\n"
    "  return html`<div class=\"block\">\n"
    "    <${Eyebrow}>${t('OTHER DEVICES')}<//>\n"
    "    ${lan.on\n"
    "      ? html`<div>${t('open to the network')}${lan.url\n"
    "            ? html`: <a class=\"ok\" href=${lan.url}>${lan.url}</a>`\n"
    "            : ' ' + t('(no network address found yet)')}</div>\n"
    "          <div class=\"note\">${t('type that address into a phone or tablet on the same Wi-Fi and add the page to the home screen. Other devices watch; settings and QUIT stay here. On Windows, allow xerabora through the firewall when it asks.')}</div>\n"
    "          <${Btn} onClick=${flip} disabled=${busy}>${t('CLOSE TO THIS PC')}<//>`\n"
    "      : html`<div class=\"note\">${t('the page is reachable from this PC only. Open it to the network and any phone, tablet or second PC on the same Wi-Fi can watch this tracker.')}</div>\n"
    "          <${Btn} onClick=${flip} primary disabled=${busy}>${t('OPEN TO THE NETWORK')}<//>`}\n"
    "    <${Msg} text=${msg[0]} good=${msg[1]} />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* ABOUT: the version this client runs, the newest release on GitHub,\n"
    "   and where to go with a problem. The release list includes\n"
    "   prereleases, which /releases/latest leaves out. */\n"
    "const REPO = 'https://github.com/hacan359/xerabora';\n"
    "const latestRelease = signal(null);\n"
    "let latestAsked = false;\n"
    "\n"
    "function askLatest() {\n"
    "  if (latestAsked) return;\n"
    "  latestAsked = true;\n"
    "  fetch('https://api.github.com/repos/hacan359/xerabora/releases?per_page=1')\n"
    "    .then(r => r.json())\n"
    "    .then(list => { if (Array.isArray(list) && list[0]) latestRelease.value = list[0]; })\n"
    "    .catch(() => { latestAsked = false; });\n"
    "}\n"
    "\n"
    "function AboutBlock() {\n"
    "  askLatest();\n"
    "  const v = S.version.value;\n"
    "  const rel = latestRelease.value;\n"
    "  const newer = rel && v && rel.tag_name !== 'v' + v;\n"
    "\n"
    "  return html`<div class=\"block\">\n"
    "    <${Eyebrow}>${t('ABOUT')}<//>\n"
    "    <div>xeRAbora <span class=\"ok\">${v ? 'v' + v : ''}</span></div>\n"
    "    ${rel && html`<div class=\"note\">${newer\n"
    "      ? tv('{tag} is out: {link}', { tag: rel.tag_name, link: html`<a class=\"ok\" href=${rel.html_url} target=\"_blank\" rel=\"noopener\">${t('download')}</a>` })\n"
    "      : t('this is the latest release')}</div>`}\n"
    "    <div class=\"note\">${t('something does not work? Read the guide first, then open an issue with the debug build\\'s logs.')}</div>\n"
    "    <div class=\"links\">\n"
    "      <a href=${REPO + '/blob/main/docs/TROUBLESHOOTING.md'} target=\"_blank\" rel=\"noopener\">${t('BEFORE YOU REPORT')}</a>\n"
    "      <a href=${REPO + '/issues'} target=\"_blank\" rel=\"noopener\">${t('ISSUES')}</a>\n"
    "      <a href=\"https://discord.gg/JZVNPF7cS2\" target=\"_blank\" rel=\"noopener\">DISCORD</a>\n"
    "      <a href=${REPO + '/releases'} target=\"_blank\" rel=\"noopener\">${t('RELEASES')}</a>\n"
    "      <a href=\"https://hacan359.github.io/xerabora/\" target=\"_blank\" rel=\"noopener\">${t('PROJECT PAGE')}</a>\n"
    "    </div>\n"
    "    <div class=\"note\">${t('Built on Open PS2 Loader, rcheevos and ps2sdk. The Android app by MrRexD. The PC client is MIT; the OPL fork keeps OPL\\'s AFL 3.0.')}</div>\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "function SettingsTab() {\n"
    "  settingsKey.value;\n"
    "  const s = S.state.peek();\n"
    "  const li = (s && s.login) || { ok: false, user: '', webapi: false };\n"
    "  const lan = (s && s.lan) || { on: false, url: '' };\n"
    "\n"
    "  if (REMOTE) {\n"
    "    return html`<div class=\"tab\"><div class=\"set\">\n"
    "      <${Eyebrow}>${t('OTHER DEVICES')}<//>\n"
    "      <div>${tv('this page is open from {host}', { host: html`<span class=\"ok\">${location.host}</span>` })}</div>\n"
    "      <div class=\"note\">${t('account, Web API key, the network switch and QUIT are changed on the PC that runs xerabora; from here you watch.')}</div>\n"
    "      ${li.ok && html`<div style=${{ marginTop: '14px' }}>${tv('signed in as {user}', { user: html`<span class=\"ok\">${li.user}</span>` })}</div>`}\n"
    "      <div style=${{ marginTop: '26px' }}><${AboutBlock} /></div>\n"
    "    </div></div>`;\n"
    "  }\n"
    "\n"
    "  return html`<div class=\"tab\"><div class=\"set\">\n"
    "    <${AccountBlock} li=${li} />\n"
    "    <${KeyBlock} li=${li} />\n"
    "    <${LanBlock} lan=${lan} />\n"
    "    <${AboutBlock} />\n"
    "  </div></div>`;\n"
    "}\n"
    "\n"
    "/* ==== 90-app.js ==== */\n"
    "/* ---- The page: header, status strip, the open tab, footer -------------- */\n"
    "\n"
    "const linkStats = computed(() => {\n"
    "  if (mode.value !== 'console') return '';\n"
    "  const fr = fast.frames.value;\n"
    "  if (fr) return t('{frames} snapshots, {skipped} skipped', { frames: fr.toLocaleString(), skipped: fast.gaps.value });\n"
    "  const pk = fast.packets.value;\n"
    "  return pk ? t('{packets} packets', { packets: pk.toLocaleString() }) : '';\n"
    "});\n"
    "\n"
    "/* The footer clock: the console session, or the following session. */\n"
    "const clockText = computed(() => {\n"
    "  const m = mode.value;\n"
    "  if (m === 'console') return fast.seconds.value ? hms(fast.seconds.value) : '';\n"
    "  if (m === 'follow') return fast.fSince.value ? hms(fast.fSince.value) : '';\n"
    "  return '';\n"
    "});\n"
    "\n"
    "function Header() {\n"
    "  const tab = S.tab.value;\n"
    "  const p = S.profile.value;\n"
    "  /* The separator is inside the points span; a narrow header hides the span. */\n"
    "  const who = p === null ? ''\n"
    "    : p.user ? html`<b>${p.user}</b><span class=\"pts\">${t('{user} \\u00b7 {points} points', { user: '', points: p.points.toLocaleString() })}</span>`\n"
    "    : t('no Web API key, see SETTINGS');\n"
    "\n"
    "  return html`<header class=\"top\"><div class=\"wrap\">\n"
    "    <a class=\"brand\" href=\"#\" onClick=${e => { e.preventDefault(); S.tab.value = 'live'; }}>\n"
    "      <span>xe<span class=\"r\">R</span><span class=\"a\">A</span>bora</span>\n"
    "      ${S.version.value && html`<span class=\"ver\">v${S.version.value}</span>`}\n"
    "    </a>\n"
    "    <nav class=\"tabs\">\n"
    "      ${TABS.map(name => html`<button key=${name} class=${tab === name ? 'on' : ''}\n"
    "        onClick=${() => { S.tab.value = name; }}>${t(name.toUpperCase())}</button>`)}\n"
    "    </nav>\n"
    "    <div class=\"hdr-right\">\n"
    "      <span class=\"who\">${who}</span>\n"
    "      <select class=\"lang\" aria-label=\"Language\" value=${lang} onChange=${e => setLang(e.target.value)}>\n"
    "        ${LANGS.map(([code, name]) => html`<option key=${code} value=${code} title=${name}>${(code || 'en').split('-')[0].toUpperCase()}</option>`)}\n"
    "      </select>\n"
    "      ${!REMOTE && html`<${Btn} danger sm onClick=${quit}>${t('QUIT')}<//>`}\n"
    "    </div>\n"
    "  </div></header>`;\n"
    "}\n"
    "\n"
    "function Status() {\n"
    "  const s = S.state.value;\n"
    "  const c = (s && s.console) || {};\n"
    "  const f = (s && s.follow) || {};\n"
    "  const li = (s && s.login) || { ok: true };\n"
    "  const m = mode.value;\n"
    "  const text = !s ? t('waiting for the console')\n"
    "    : c.connected ? t('console live at {ip}', { ip: c.ip })\n"
    "    : f.active ? t('following {game} via RetroAchievements', { game: s.game.title || '' }) + (f.online ? ' · ' + t('playing now') : '')\n"
    "    : !li.ok ? html`<span class=\"warn\">${t('not signed in to RetroAchievements &mdash; open SETTINGS to sign in')}</span>`\n"
    "    : t('waiting for the console');\n"
    "\n"
    "  return html`<div class=\"status\"><div class=\"wrap\">\n"
    "    <span class=${'dot' + ((c.connected || f.active) ? ' on' : '')} />\n"
    "    ${m !== 'idle' && html`<span class=\"mode\">${t(m === 'console' ? 'CONSOLE' : 'FOLLOWING')}</span>`}\n"
    "    <span class=\"text\">${text}</span>\n"
    "    <span class=\"counters\">${linkStats}</span>\n"
    "  </div></div>`;\n"
    "}\n"
    "\n"
    "async function quit() {\n"
    "  if (!confirm(t('Quit xerabora? Console telemetry and unlocks stop.'))) return;\n"
    "  try { await postForm('/quit', {}); } catch (err) { /* it is going away */ }\n"
    "  S.closed.value = true;\n"
    "}\n"
    "\n"
    "function Footer() {\n"
    "  const s = S.state.value;\n"
    "  const connected = !!(s && s.console.connected);\n"
    "  return html`<footer><div class=\"wrap\">\n"
    "    <${Chip} on cls=\"static\" title=\"every unlock is softcore\">${t('SOFTCORE')}<//>\n"
    "    <${Chip} on=${connected} cls=\"static\" title=\"the gold flash on the TV: lit while a console streams\">${t('FLASH')}<//>\n"
    "    <span class=\"clock\">${clockText}</span>\n"
    "  </div></footer>`;\n"
    "}\n"
    "\n"
    "function App() {\n"
    "  if (S.closed.value)\n"
    "    return html`<div class=\"closed\">${t('xerabora is closed. This tab can be closed too.')}</div>`;\n"
    "\n"
    "  const tab = S.tab.value;\n"
    "  const err = S.error.value;\n"
    "  return html`<div class=\"app\">\n"
    "    <${Header} />\n"
    "    <${Status} />\n"
    "    <main class=\"wrap\">\n"
    "      ${err && html`<div class=\"err\">${'page error: ' + err}</div>`}\n"
    "      ${tab === 'live' ? html`<${LiveTab} />`\n"
    "        : tab === 'library' ? html`<${LibraryTab} />`\n"
    "        : tab === 'game' ? html`<${GameTab} />`\n"
    "        : tab === 'boards' ? html`<${BoardsTab} />`\n"
    "        : html`<${SettingsTab} />`}\n"
    "    </main>\n"
    "    <${Footer} />\n"
    "    <${Toast} />\n"
    "    <${PowerOn} />\n"
    "  </div>`;\n"
    "}\n"
    "\n"
    "/* Uncaught errors go to the error box at the top of main. */\n"
    "function showError(err) { S.error.value = String(err && err.stack ? err.stack : err); }\n"
    "window.addEventListener('error', e => showError(e.error || e.message));\n"
    "window.addEventListener('unhandledrejection', e => showError(e.reason));\n"
    "\n"
    "/* data-mode on <html>: the accent and the washes follow it in CSS. */\n"
    "effect(() => { document.documentElement.dataset.mode = mode.value; });\n"
    "\n"
    "/* #tab=boards opens straight on a tab; #game=5761 opens that game's card. */\n"
    "{\n"
    "  const q = new URLSearchParams(location.hash.slice(1) || location.search);\n"
    "  const want = q.get('tab');\n"
    "  const game = +q.get('game');\n"
    "\n"
    "  if (game > 0) S.gameId.value = game;\n"
    "  S.tab.value = TABS.includes(want) ? want : game > 0 ? 'game' : 'live';\n"
    "}\n"
    "\n"
    "render(html`<${App} />`, document.getElementById('app'));\n"
    "loadProfile();\n"
    "stream();\n"
    "tick();\n"
    "\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    ;
